type Props = { userId: string };

function ChatInput({ userId }: Props) {
  const [bottom, setBottom] = useState(0);

  useEffect(async () => {
    const prefs = await loadPrefs(userId);
    if (!prefs.liftOnKeyboard) return;
    const sub = Keyboard.addListener('keyboardDidShow', (e) => {
      setBottom(e.endCoordinates.height);
    });
    return () => sub.remove();
  }, [userId]);

  return <Composer style={{ marginBottom: bottom }} />;
}

const emitter = new NativeEventEmitter(NativeModules.Downloader);

type Progress = { id: string; percent: number };

export function useDownloadProgress(id: string): number {
  const [percent, setPercent] = useState(0);

  useEffect(() => {
    emitter.addListener('onProgress', (e: Progress) => {
      if (e.id === id) setPercent(e.percent);
    });
    return () => emitter.removeAllListeners('onProgress');
  }, [id]);

  return percent;
}

type Props = NativeStackScreenProps<RootStackParamList, 'Payment'>;

function PaymentScreen({ navigation, route }: Props) {
  const { orderId } = route.params;
  const [status, setStatus] = useState<OrderStatus>('pending');

  useEffect(() => {
    const id = setInterval(async () => {
      const next = await fetchOrderStatus(orderId);
      setStatus(next);
      if (next === 'paid') navigation.navigate('Receipt', { orderId });
    }, 3000);
    return () => clearInterval(id);
  }, [orderId, navigation]);

  return <StatusBanner status={status} />;
}
